                Type arg = args[i];
                // Resolve arg recursively: if it is TypeVariable, may map from higher level
                if (arg instanceof TypeVariable && map.containsKey(arg)) {
                    arg = map.get(arg);
                }
                map.put(params[i], arg);
            }
            target = rawSuper;
        } else {
            target = target.getSuperclass();
        }
    }
    return map;
}

