        // Superclass
        Type genericSuper = cls.getGenericSuperclass();
        if (genericSuper instanceof ParameterizedType) {
            ParameterizedType superParam = (ParameterizedType) genericSuper;
            Class<?> rawSuper = (Class<?>) superParam.getRawType();
            TypeVariable<?>[] superParams = rawSuper.getTypeParameters();
            Type[] superArgs = superParam.getActualTypeArguments();
            for (int i = 0; i < superParams.length; i++) {
